function d(t,n){const e=Math.floor(Math.random()*(n-t+1))+t;return new Promise(o=>setTimeout(o,e))}function m(t,n,e){const o=(n-1)*e,s=o+e;return{items:t.slice(o,s),total:t.length,page:n,pageSize:e}}function g(t,n,e){return[...t].sort((o,s)=>{const r=o[n],a=s[n];if(r==null)return 1;if(a==null)return-1;let c=0;return typeof r=="string"&&typeof a=="string"?c=r.localeCompare(a,"zh-CN"):typeof r=="number"&&typeof a=="number"?c=r-a:c=String(r).localeCompare(String(a)),e==="ascend"?c:-c})}function h(t,n,e){if(!e)return t;const o=e.toLowerCase();return t.filter(s=>{const r=s[n];return r!=null&&String(r).toLowerCase().includes(o)})}function u(t,n){return Math.random()*(n-t)+t}function p(t){return`${t}-${Date.now()}-${Math.random().toString(36).slice(2,9)}`}function w(t,n,e,o){const s=[],r=Date.now(),a=Math.floor(t*24*60/n),c=n*60*1e3;for(let i=a;i>=0;i--){const l=new Date(r-i*c).toISOString(),f=Math.max(0,e+(Math.random()-.5)*2*o);s.push([l,parseFloat(f.toFixed(2))])}return s}function M(){return[u(10,192)|0,u(0,255)|0,u(0,255)|0,u(1,254)|0].join(".")}function S(t){const n=String(Math.floor(Math.random()*99999)+1).padStart(5,"0");switch(t){case"eNB":return`ENB${n}`;case"gNB":return`GNB${n}`;case"CPE":return`CPE${n}`;case"eGW":return`EGW${n}`;default:return`DEV${n}`}}export{M as a,p as b,w as c,d,h as f,S as g,m as p,g as s};
